import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])

    if n == 1:
        print(1)
        return

    result = []
    current_gcd = 1
    count = 0
    total_needed = n

    while len(result) < total_needed:
        next_val = current_gcd * 2
        if next_val > n:
            next_val = n

        gap = next_val - current_gcd
        if gap == 0:
            break

        num_to_add = min(total_needed - len(result), gap)

        if num_to_add > 0:
            result.extend([current_gcd] * num_to_add)
            current_gcd = next_val

        if current_gcd == n:
            break

        if len(result) >= total_needed:
            break

        if current_gcd < n:
            result.append(current_gcd)
            current_gcd *= 2
            if current_gcd > n:
                current_gcd = n

    while len(result) < total_needed:
        result.append(n)

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
